/* D0 design exploration only. Synthetic in-memory data. No API, uploads, storage or application imports. */
const params = new URLSearchParams(location.search);
const theme = ['atlas','medina','horizon'].includes(params.get('theme')) ? params.get('theme') : 'atlas';
const page = ['home','product','store','supplier','editor','buyer','messages','compare'].includes(params.get('page')) ? params.get('page') : 'home';
const lang = params.get('lang') === 'fr' ? 'fr' : 'ar';
const t = (ar, fr) => lang === 'ar' ? ar : fr;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.documentElement.lang = lang; document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr'; document.body.dataset.theme = theme; document.body.dataset.page = page;
const titles = {home:t('السوق','Le marché'),product:t('تفاصيل المنتج','Le produit'),store:t('دار التوريد','Dar Appro'),supplier:t('مساحة المورد','Espace fournisseur'),editor:t('إضافة منتج','Ajouter un produit'),buyer:t('طلباتي','Mes demandes'),messages:t('المحادثات','Conversations'),compare:t('المقارنة','Comparaison')};
document.title = `Jomla.ma · ${titles[page]} · D0 / ${theme}`;
const href = (p, extras = {}) => '?' + new URLSearchParams({theme,page:p,lang,...extras});
const iconPaths = {search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0', grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',arrow:'M5 12h14m-6-6 6 6-6 6',camera:'M3 7h4l2-3h6l2 3h4v14H3zM16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bag:'M4 7h16l-1 14H5zM8 7V5a4 4 0 0 1 8 0v2',chat:'M3 3h18v14H8l-5 4zM7 8h10M7 12h7',store:'M3 10h18L19 3H5zM5 10v11h14V10M9 21v-7h6v7',plus:'M12 4v16M4 12h16',filter:'M4 6h16M7 12h10M10 18h4',check:'M4 12l5 5L20 6',close:'M5 5l14 14M19 5 5 19',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 12h8M8 16h8',copy:'M8 8h13v13H8zM16 8V3H3v13h5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0M15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',compare:'M8 3v18M16 3v18M4 8h8M12 16h8',leaf:'M20 3C8 1 1 10 7 17s16 2 13-14M5 21 16 8',logout:'M10 3H3v18h7M8 12h13m-5-5 5 5-5 5'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[name] || iconPaths.grid}"/></svg>`;
const products = [
 {id:'ceramics',name:t('كوب خزفي بخطوط خضراء','Tasse en céramique, rayures vertes'),category:t('المنزل والديكور','Maison & décoration'),price:42,moq:48,unit:t('قطعة','pièce'),city:t('فاس','Fès'),img:'ceramics'},
 {id:'oil',name:t('زيت زيتون · عبوة زجاجية 1 لتر','Huile d’olive · bouteille de 1 litre'),category:t('المواد الغذائية','Alimentation'),price:95,moq:24,unit:t('عبوة','bouteille'),city:t('مكناس','Meknès'),img:'oil'},
 {id:'textile',name:t('منشفة قطنية بنسيج طبيعي','Serviette en coton, tissage naturel'),category:t('النسيج','Textile'),price:28,moq:60,unit:t('قطعة','pièce'),city:t('الدار البيضاء','Casablanca'),img:'textile'},
 {id:'basket',name:t('سلة تخزين من الألياف الطبيعية','Panier de rangement en fibres naturelles'),category:t('المنزل والديكور','Maison & décoration'),price:75,moq:20,unit:t('قطعة','pièce'),city:t('مراكش','Marrakech'),img:'basket'}
];
const p = products[0];
const money = n => `${new Intl.NumberFormat(lang === 'ar' ? 'ar-MA' : 'fr-MA', {maximumFractionDigits:0}).format(n)} <span class="currency">MAD</span>`;
const demo = t('تصور D0 · بيانات ورسوم توضيحية فقط','Concept D0 · données et illustrations fictives');
const brand = `<a class="brand" href="${href('home')}" aria-label="Jomla.ma — ${t('السوق','le marché')}"><span class="brand-mark">ج</span><span dir="ltr">jomla<span class="brand-dot">.</span><small>ma</small></span></a>`;
const search = (compact=false) => `<form class="search ${compact?'compact':''}" data-search><label class="sr-only" for="market-search">${t('ابحث في المنتجات','Rechercher des produits')}</label>${icon('search')}<input id="market-search" name="q" placeholder="${t('ما الذي تبحث عنه بالجملة؟','Que cherchez-vous en gros ?')}" autocomplete="off"><button class="image-search" type="button" data-image aria-label="${t('البحث بالصورة','Recherche par image')}">${icon('camera')}</button><button class="btn primary" type="submit">${t('ابحث','Rechercher')}</button></form>`;
const langLink = `<a class="lang-link" lang="${lang==='ar'?'fr':'ar'}" href="${href(page,{lang:lang==='ar'?'fr':'ar'})}">${lang==='ar'?'FR':'العربية'}</a>`;
function header(work=false) { return `<div class="demo-strip">${demo}<a href="index.html">${t('استعراض الاتجاهات','Explorer les directions')}</a></div><header class="header"><div class="header-inner">${brand}${work?`<span class="workspace-title">${t('مساحة العمل','Espace de travail')}</span>`:search(true)}<nav class="account-nav" aria-label="${t('الحساب واللغة','Compte et langue')}">${langLink}<a class="plain account" href="${href(work?'home':'buyer')}">${icon(work?'store':'user')}<span>${work?t('زيارة السوق','Voir le marché'):t('مساحتي','Mon espace')}</span></a>${!work?`<a class="btn outline sell" href="${href('supplier')}">${t('بع بالجملة','Vendre en gros')}</a>`:''}</nav></div>${!work?`<nav class="market-nav wrap" aria-label="${t('التنقل الرئيسي','Navigation principale')}"><a class="${page==='home'?'active':''}" href="${href('home')}">${icon('grid')}${t('كل المنتجات','Tous les produits')}</a><a href="${href('store')}">${t('المتاجر','Les boutiques')}</a><a href="${href('home')}#categories">${t('تصفح الفئات','Par catégories')}</a><button class="plain" data-rfq>${t('طلب عرض سعر','Demander un devis')}</button><span class="nav-note">${t('سوق الجملة المغربي','Le marché de gros marocain')}</span></nav>`:''}</header>`; }
function card(prod, i=0) {return `<article class="product-card"><a class="product-visual" href="${href('product')}" aria-label="${esc(prod.name)}"><img src="assets/${prod.img}.svg" width="640" height="480" ${i>1?'loading="lazy"':''} alt="${esc(prod.name)} — ${t('رسم توضيحي','illustration')}"><span class="image-tag">${esc(prod.category)}</span></a><div class="product-info"><a href="${href('product')}" class="product-name">${esc(prod.name)}</a><p class="product-price">${money(prod.price)}<small> / ${prod.unit}</small></p><p class="moq">${t('أقل طلب','Minimum')} <strong>${prod.moq} ${prod.unit}</strong></p><a href="${href('store')}" class="supplier-line">${icon('store')}${t('دار التوريد','Dar Appro')}<span>· ${prod.city}</span></a><div class="card-actions"><button class="btn outline" data-rfq>${t('اطلب عرض سعر','Demander un devis')}</button><button class="compare-btn" data-compare="${prod.id}" aria-pressed="false" aria-label="${t('قارن','Comparer')} ${esc(prod.name)}">${icon('compare')}</button></div></div></article>`;}
function catalog() {return `<section class="catalog wrap" id="catalog"><div class="section-head"><div><span class="eyebrow">${t('اكتشف ما يناسب تجارتك','POUR VOTRE ACTIVITÉ')}</span><h2 id="results-title">${t('منتجات لاستكشافها','Des produits à découvrir')}</h2></div><div class="catalog-tools"><button class="btn outline" data-filters>${icon('filter')}${t('تصفية','Filtres')}</button><label class="sort"><span class="sr-only">${t('ترتيب المنتجات','Trier les produits')}</span><select id="sort"><option value="default">${t('الترتيب الافتراضي','Ordre par défaut')}</option><option value="asc">${t('السعر: من الأقل','Prix croissant')}</option></select></label></div></div><p id="search-status" role="status" class="search-status" hidden></p><div class="product-grid" id="product-grid">${products.map(card).join('')}</div></section>`;}
function home() {return `${header()}<main id="main"><section class="home-hero wrap"><div class="hero-copy"><span class="eyebrow">${t('جملة مغربية. فرص أقرب.','LE GROS, PLUS PROCHE.')}</span><h1>${theme==='medina'?t('تجارة بقرب الناس.<br>ومنتجات تستحق الاكتشاف.','Le goût des produits.<br>Le sens du commerce.'):theme==='horizon'?t('ابحث بوضوح.<br>وتفاوض بثقة.','Trouvez le bon produit.<br>Clarifiez votre besoin.'):t('كل ما تحتاجه تجارتك،<br><em>بداية من هنا.</em>','Votre prochain fournisseur<br><em>commence ici.</em>')}</h1><p>${t('اكتشف المنتجات والمتاجر. قارن الكميات والأسعار، ثم اطلب عرضاً يناسب احتياجك.','Explorez les produits et les boutiques. Comparez les quantités et les prix, puis demandez un devis adapté.')}</p><div class="hero-actions"><a class="btn primary" href="#catalog">${t('تصفح المنتجات','Explorer les produits')}${icon('arrow')}</a><button class="text-link" data-rfq>${t('لديك طلب محدد؟','Un besoin précis ?')}</button></div><p class="quiet hero-foot">${t('تصفح دون حساب · سجل الدخول عند إرسال طلبك','Parcourez sans compte · Connectez-vous pour envoyer une demande')}</p></div><div class="hero-art"><img src="assets/hero.svg" width="800" height="640" alt="${t('تكوين توضيحي لمنتجات مغربية، ليس صورة مورد','Composition illustrée, pas une photo de fournisseur')}"><div class="art-caption"><span>${t('للبيت، للمتجر، ولتجارتك','Pour la maison, la boutique et votre activité')}</span><small>${t('منتجات وأسماء تجريبية','Produits et noms fictifs')}</small></div></div>${theme==='horizon'?`<aside class="quick-request"><span class="quick-icon">${icon('file')}</span><h2>${t('ابدأ بالاحتياج','Partez de votre besoin')}</h2><p>${t('حدد المنتج والكمية. تابع عرض المورد والمحادثة في مساحتك.','Précisez le produit et la quantité. Retrouvez l’offre et la conversation dans votre espace.')}</p><button class="btn primary" data-rfq>${t('طلب عرض سعر','Demander un devis')}</button></aside>`:''}</section><section class="category-strip wrap" id="categories" aria-label="${t('فئات المنتجات','Catégories')}">${[t('المنزل والديكور','Maison & décoration'),t('المواد الغذائية','Alimentation'),t('النسيج','Textile'),t('كل المنتجات','Tous les produits')].map((c,i)=>`<button data-category="${i}" class="category"><span class="category-icon">${icon(['bag','leaf','grid','store'][i])}</span><span>${c}</span>${icon('arrow')}</button>`).join('')}</section>${catalog()}<section class="sourcing-banner wrap"><div><span class="eyebrow">${t('احتياج مختلف؟','UN BESOIN PARTICULIER ?')}</span><h2>${t('صف طلبك بدل البحث طويلاً.','Décrivez votre besoin, simplement.')}</h2><p>${t('مسار طلب التوريد الحالي يبقى متاحاً من حساب المشتري.','La demande d’approvisionnement reste accessible dans votre espace acheteur.')}</p></div><a href="${href('buyer')}" class="btn outline">${t('مساحة المشتري','Espace acheteur')}${icon('arrow')}</a></section></main>${footer()}`;}
function crumb() {return `<nav class="breadcrumbs" aria-label="${t('مسار الصفحة','Fil d’Ariane')}"><a href="${href('home')}">${t('السوق','Marché')}</a><span>/</span><a href="${href('store')}">${t('دار التوريد','Dar Appro')}</a><span>/</span><span>${page==='store'?t('المتجر','Boutique'):t('المنزل والديكور','Maison & décoration')}</span></nav>`;}
function product() {return `${header()}<main id="main" class="wrap">${crumb()}<div class="product-detail"><section class="gallery" aria-label="${t('صور المنتج','Images du produit')}"><div class="gallery-stage"><img id="main-product-image" src="assets/ceramics.svg" width="640" height="480" alt="${esc(p.name)} — ${t('رسم توضيحي','illustration')}"><span class="gallery-label">${t('رسم توضيحي · ليس منتجاً معروضاً للبيع','Illustration · aucun produit en vente')}</span></div><div class="thumbs"><button class="selected" data-thumb="ceramics" aria-label="${t('الصورة الرئيسية','Image principale')}" aria-pressed="true"><img src="assets/ceramics.svg" width="80" height="60" alt=""></button><button data-thumb="hero" aria-label="${t('تفصيل توضيحي','Composition illustrée')}" aria-pressed="false"><img src="assets/hero.svg" width="80" height="60" alt=""></button><span>${t('الصورة لا تثبت الجودة أوهوية المنتج','L’image ne certifie ni qualité ni identité')}</span></div></section><section class="product-summary"><span class="eyebrow">${p.category}</span><h1>${p.name}</h1><a href="${href('store')}" class="store-byline">${icon('store')}${t('دار التوريد','Dar Appro')}<span>· ${p.city}</span></a><p class="detail-intro">${t('خزف بلون طبيعي وخطوط خضراء. وصف توضيحي قصير يترك المواصفات قابلة للمراجعة قبل الاتفاق.','Une céramique aux tons naturels et rayures vertes. Une description claire, à confirmer avec le fournisseur avant accord.')}</p><div class="price-top"><strong>${money(42)}</strong><span>/ ${t('قطعة','pièce')}</span><span class="availability"><i></i>${t('متوفر بحسب المورد','Disponible selon le fournisseur')}</span></div><div class="tiers" aria-label="${t('شرائح الأسعار','Tarifs par quantité')}">${[[48,95,42],[96,239,39],[240,'+',36]].map(([a,b,c])=>`<div><span dir="ltr">${a}${b==='+'?'+':'–'+b}</span><strong>${money(c)}</strong><small>${t('للقطعة','par pièce')}</small></div>`).join('')}</div><div class="quantity-row"><label for="quantity">${t('الكمية المطلوبة','Quantité souhaitée')}<small>${t('أقل طلب: 48 قطعة','Minimum : 48 pièces')}</small></label><input id="quantity" type="number" min="48" step="1" value="48" inputmode="numeric"></div><p class="estimate" id="estimate">${t('تقدير أولي','Estimation indicative')} <strong>${money(2016)}</strong> · ${t('ليس اتفاقاً تجارياً','ne vaut pas accord')}</p><button class="btn primary main-rfq" data-rfq>${t('طلب عرض سعر لهذا المنتج','Demander un devis pour ce produit')}${icon('arrow')}</button><p class="login-note">${t('التصفح متاح للجميع. إرسال الطلب يتطلب دخول المشتري.','Consultation libre. Un compte acheteur est requis pour envoyer la demande.')}</p><div class="detail-actions"><button class="text-link" data-share>${icon('copy')}${t('مشاركة الرابط','Partager le lien')}</button><button class="text-link" data-compare="ceramics" aria-pressed="false">${icon('compare')}${t('أضف للمقارنة','Comparer')}</button></div></section></div><section class="details-section"><div><h2>${t('تفاصيل تهم قرارك','Les détails qui comptent')}</h2><dl class="specs"><div><dt>${t('وحدة البيع','Unité de vente')}</dt><dd>${t('قطعة','Pièce')}</dd></div><div><dt>${t('الحد الأدنى للطلب','Commande minimum')}</dt><dd>48 ${t('قطعة','pièces')}</dd></div><div><dt>${t('العملة','Devise')}</dt><dd>MAD</dd></div><div><dt>${t('مدينة المورد','Ville du fournisseur')}</dt><dd>${p.city}</dd></div></dl></div><aside class="supplier-mini"><span class="store-avatar">د</span><div><h3>${t('دار التوريد','Dar Appro')}</h3><p>${t('معلومات المورد العامة فقط','Informations publiques du fournisseur')}</p><a class="text-link" href="${href('store')}">${t('زيارة المتجر','Voir la boutique')}${icon('arrow')}</a></div></aside></section><section class="no-reviews"><h2>${t('تقييمات المورد','Avis sur le fournisseur')}</h2><p>${t('لا توجد تقييمات في هذه العينة. يظهر العدد والمحتوى الحقيقيان فقط عند توفرهما.','Aucun avis dans cet exemple. Seuls les avis réels seront affichés lorsqu’ils existent.')}</p></section></main><div class="mobile-rfq"><span><strong>${money(42)}</strong><small>${t('أقل طلب 48 قطعة','Min. 48 pièces')}</small></span><button class="btn primary" data-rfq>${t('اطلب عرض سعر','Demander un devis')}</button></div>${footer()}`;}
function store() {return `${header()}<main id="main" class="wrap">${crumb()}<section class="store-cover"><div class="store-monogram">د<span>DA</span></div><div class="store-heading"><span class="eyebrow">${t('متجر عام · نموذج توضيحي','BOUTIQUE PUBLIQUE · EXEMPLE')}</span><h1>${t('دار التوريد','Dar Appro')}</h1><p>${t('منتجات للمنزل وتجارة الجملة. وصف مختصر يقدمه المورد عن نشاطه.','Des produits pour la maison et le commerce de gros. Une présentation courte, rédigée par le fournisseur.')}</p><span class="location">${icon('pin')}${t('فاس، المغرب','Fès, Maroc')}</span></div><button class="btn outline" data-share>${icon('copy')}${t('شارك المتجر','Partager la boutique')}</button></section><div class="store-layout"><aside class="store-about"><h2>${t('عن المتجر','À propos')}</h2><p>${t('هذه معلومات عامة اصطناعية، وليست شركة حقيقية.','Informations publiques fictives ; cette entreprise n’existe pas.')}</p><dl><dt>${t('المورد','Fournisseur')}</dt><dd>${t('دار التوريد','Dar Appro')}</dd><dt>${t('المدينة','Ville')}</dt><dd>${t('فاس','Fès')}</dd><dt>${t('هاتف تجريبي','Téléphone fictif')}</dt><dd dir="ltr">+212 600 000 000</dd></dl><p class="quiet">${t('لا يعرض المتجر وثائق الحساب أو المسودات.','Les documents du compte et les brouillons restent privés.')}</p></aside><section class="store-catalog"><div class="store-tools"><h2>${t('منتجات المتجر','Produits de la boutique')} <span class="count">4</span></h2><form data-search class="store-search"><label class="sr-only" for="store-query">${t('البحث داخل المتجر','Rechercher dans la boutique')}</label><input id="store-query" name="q" placeholder="${t('ابحث داخل المتجر','Rechercher dans la boutique')}"><button class="icon-button" aria-label="${t('ابحث','Rechercher')}">${icon('search')}</button></form></div><p id="search-status" class="search-status" role="status" hidden></p><div id="product-grid" class="product-grid">${products.map(card).join('')}</div><p class="quiet">${t('تظهر المنتجات المنشورة والمؤهلة فقط.','Seuls les produits publiés et éligibles sont affichés.')}</p></section></div></main>${footer()}`;}
const navItems = [['supplier','grid',t('نظرة عامة','Vue d’ensemble')],['supplier','bag',t('المنتجات','Produits')],['store','store',t('المتجر','Boutique')],['buyer','file',t('طلبات الأسعار','Demandes de devis')],['messages','chat',t('المحادثات','Conversations')]];
function side() {return `<aside class="workspace-side"><div class="workspace-store"><span class="store-avatar">د</span><div><strong>${t('دار التوريد','Dar Appro')}</strong><small>${t('حساب مورد تجريبي','Compte fournisseur fictif')}</small></div></div><nav aria-label="${t('مساحة المورد','Espace fournisseur')}">${navItems.map(([p,i,s],n)=>`<a href="${href(p)}" class="${page===p&&n===0?'active':''}">${icon(i)}${s}${i==='file'?'<span class="nav-count">2</span>':''}</a>`).join('')}<a href="${href('editor')}">${icon('plus')}${t('إضافة منتج','Ajouter un produit')}</a></nav><div class="side-bottom"><span class="quiet">${t('صلاحيات الحساب','Droits du compte')}</span><p>${t('تظهر الأقسام المصرح بها فقط عند التنفيذ.','À l’implémentation, seuls les modules autorisés seront visibles.')}</p></div></aside>`;}
function supplier() {return `${header(true)}<main id="main" class="workspace wrap">${side()}<div class="workspace-main"><div class="workspace-welcome"><div><span class="eyebrow">${t('خطوتك التالية، بوضوح','VOTRE PROCHAINE ACTION')}</span><h1>${t('أهلاً بك في مساحتك','Bienvenue dans votre espace')}</h1><p>${t('تابع منتجاتك وطلبات الأسعار من مكان واحد.','Vos produits et vos demandes de devis, au même endroit.')}</p></div><a class="btn primary" href="${href('editor')}">${icon('plus')}${t('أضف منتجاً','Ajouter un produit')}</a></div><div class="metrics">${[[12,t('منتج منشور','Produits publiés'),'bag'],[3,t('مسودات خاصة','Brouillons privés'),'file'],[2,t('طلبان بانتظار الرد','Demandes à traiter'),'chat']].map(([n,s,i])=>`<div class="metric">${icon(i)}<strong>${n}</strong><span>${s}</span></div>`).join('')}</div><section class="panel tasks"><div class="section-head"><h2>${t('يحتاج انتباهك','À traiter en priorité')}</h2><span class="count">2</span></div><a class="task-row" href="${href('messages')}"><span class="task-icon">${icon('chat')}</span><div><strong>${t('طلب سعر جديد · 96 كوباً خزفياً','Nouvelle demande · 96 tasses')}</strong><p>${t('راجع الكمية والملاحظات قبل تقديم العرض.','Vérifiez la quantité et les remarques avant de répondre.')}</p></div><span class="text-link">${t('افتح الطلب','Voir la demande')}${icon('arrow')}</span></a><a class="task-row" href="${href('editor')}"><span class="task-icon">${icon('file')}</span><div><strong>${t('مسودة تحتاج تحديد التوفر','Un brouillon sans disponibilité')}</strong><p>${t('تبقى خاصة حتى مراجعة البيانات واعتماد النشر.','Il reste privé jusqu’à votre validation et sa publication.')}</p></div><span class="text-link">${t('أكمل البيانات','Compléter')}${icon('arrow')}</span></a></section><section class="panel recent"><div class="section-head"><h2>${t('منتجاتك الأخيرة','Vos derniers produits')}</h2><button class="text-link" data-demo>${t('عرض الكل','Tout voir')}</button></div><div class="mini-products">${products.slice(0,2).map((q,i)=>`<article><img src="assets/${q.img}.svg" width="100" height="80" alt="${esc(q.name)}"><div><h3>${q.name}</h3><p>${money(q.price)} / ${q.unit}</p><span class="status ${i?'draft':'published'}">${i?t('مسودة خاصة','Brouillon privé'):t('منشور','Publié')}</span></div><a class="text-link" href="${href('editor')}">${t('تعديل','Modifier')}</a></article>`).join('')}</div></section><aside class="verification-note"><span class="neutral-symbol">i</span><div><h3>${t('توثيق المورد اختياري','La vérification est facultative')}</h3><p>${t('لم يقدم هذا الحساب التجريبي طلب توثيق. تبقى وثائق الحساب خاصة، ولا تظهر شارة قبل الاعتماد الفعلي.','Ce compte fictif n’a pas demandé de vérification. Les documents restent privés ; aucun badge ne précède une validation réelle.')}</p></div><button class="text-link" data-verification>${t('اعرف التفاصيل','En savoir plus')}</button></aside></div></main>${footer()}`;}
const editorData = {name:p.name,category:p.category,store:t('دار التوريد','Dar Appro'),description:t('كوب خزفي بخطوط خضراء. راجع المواصفات قبل النشر.','Tasse en céramique à rayures vertes. À vérifier avant publication.'),price:'42',moq:'48',currency:'MAD',unit:t('قطعة','pièce'),availability:'available',rights:false,approved:false};
let step = 1;
const field = (name,label,value,type='text',extra='') => `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function stepContent() {if(step===1)return `<div class="editor-columns"><div class="upload-demo"><img src="assets/ceramics.svg" width="640" height="480" alt="${t('معاينة صورة توضيحية','Aperçu illustratif')}"><button class="btn outline" type="button" data-demo>${icon('plus')}${t('اختيار صورة من جهازك','Choisir une image')}</button><p>${t('تمثيل للرفع المدار فقط. لا تُرفع ملفات في هذا النموذج.','Simulation de l’import géré. Aucun fichier n’est envoyé ici.')}</p><label class="check"><input name="rights" type="checkbox" ${editorData.rights?'checked':''}>${t('أملك حق استخدام الصورة أوترخيصها','Je possède les droits ou une licence sur cette image')}</label><button class="text-link" type="button" data-ai>${icon('camera')}${t('اقتراح وصف من الصورة · اختياري','Proposer une description · facultatif')}</button></div><div class="fields">${field('name',t('اسم المنتج','Nom du produit'),editorData.name,'text','required maxlength="200"')}<label class="field">${t('الفئة','Catégorie')}<select name="category"><option>${editorData.category}</option><option>${t('النسيج','Textile')}</option></select></label><label class="field">${t('المتجر','Boutique')}<select name="store"><option>${editorData.store}</option></select><small>${t('متجر معتمد في هذا المثال','Boutique approuvée dans cet exemple')}</small></label><label class="field">${t('الوصف','Description')}<textarea name="description" rows="4">${esc(editorData.description)}</textarea></label></div></div>`;
if(step===2)return `<div class="fields two-columns">${field('price',t('سعر الوحدة','Prix unitaire'),editorData.price,'number','min="0" step="0.01" required')}${field('currency',t('العملة','Devise'),editorData.currency,'text','required')}${field('moq',t('أقل كمية للطلب','Commande minimum'),editorData.moq,'number','min="1" step="1" required')}${field('unit',t('وحدة البيع','Unité de vente'),editorData.unit,'text','required')}<label class="field">${t('التوفر بحسب معلوماتك','Disponibilité selon vos informations')}<select name="availability"><option value="available">${t('متوفر','Disponible')}</option><option value="unknown" ${editorData.availability==='unknown'?'selected':''}>${t('لم أحدد بعد','À renseigner')}</option></select></label><div class="field"><span>${t('الأسعار حسب الكمية','Tarifs par quantité')}</span><button class="btn outline" type="button" data-demo>${icon('plus')}${t('إضافة شريحة سعر · اختياري','Ajouter un palier · facultatif')}</button></div></div><p class="form-hint">${t('في التنفيذ: يبقى خيار «السعر عند الطلب» وكل حقول المحرر الحالي متاحاً. لا نغير قواعد النشر.','À l’implémentation : conserver le prix sur demande et tous les champs actuels, sans changer les règles de publication.')}</p>`;
return `<div class="review-product"><img src="assets/ceramics.svg" width="220" height="165" alt=""><div><span class="eyebrow">${t('راجع ما سيظهر للزائر','VÉRIFIEZ L’APERÇU PUBLIC')}</span><h2>${esc(editorData.name)}</h2><p><strong>${money(Number(editorData.price)||0)}</strong> / ${esc(editorData.unit)}</p><p>${t('أقل طلب','Minimum')} ${esc(editorData.moq)} ${esc(editorData.unit)} · ${esc(editorData.store)}</p><p>${esc(editorData.description)}</p></div></div><div class="privacy-hint">${icon('file')}<p>${t('المسودة وصورها خاصة. النشر لا يتم إلا بعد استيفاء الأهلية والتأكيد؛ لا تجعل معاينة الصورة ملفاً عاماً.','Le brouillon et ses images restent privés. La publication exige éligibilité et confirmation ; un aperçu ne rend pas un fichier public.')}</p></div><label class="check approval"><input name="approved" type="checkbox" ${editorData.approved?'checked':''}>${t('راجعت الصورة وحقوقها والوصف والسعر والكمية والتوفر وأعتمد نشر البيانات.','J’ai vérifié l’image, les droits, la description, les prix, les quantités et la disponibilité, et j’approuve la publication.')}</label>`;}
function editorBody() {return `<div class="editor-head"><a class="text-link" href="${href('supplier')}">${t('مساحتي','Mon espace')}</a><h1 tabindex="-1" id="step-heading">${t('إضافة منتج، خطوة بخطوة','Ajouter un produit, pas à pas')}</h1><p>${t('يمكنك حفظ مسودة خاصة في أي وقت. النشر خطوة صريحة في النهاية.','Enregistrez un brouillon privé à tout moment. La publication reste une étape explicite.')}</p></div><ol class="steps" aria-label="${t('خطوات إضافة المنتج','Étapes de création')}">${[t('الصورة والتعريف','Image & présentation'),t('السعر والكمية','Prix & quantités'),t('المراجعة والنشر','Vérifier & publier')].map((s,i)=>`<li class="${step===i+1?'current':step>i+1?'done':''}" ${step===i+1?'aria-current="step"':''}><span>${step>i+1?icon('check'):i+1}</span><strong>${s}</strong></li>`).join('')}</ol><form id="editor-form" class="panel editor-panel"><div class="step-title"><span class="eyebrow">${t('الخطوة','ÉTAPE')} ${step} / 3</span><h2>${[t('عرّف المشتري بمنتجك','Présentez votre produit'),t('وضح شروط الجملة','Précisez les conditions de gros'),t('مراجعة أخيرة قبل النشر','Dernière vérification')][step-1]}</h2></div>${stepContent()}<div class="editor-footer"><button class="text-link" type="button" data-save>${t('حفظ مسودة خاصة','Enregistrer un brouillon privé')}</button><div>${step>1?`<button class="btn outline" type="button" data-prev>${t('السابق','Précédent')}</button>`:''}<button class="btn primary" type="submit" id="editor-next" ${step===3&&(!editorData.approved||!editorData.rights||editorData.availability==='unknown')?'disabled':''}>${step===3?t('اعتماد النشر · معاينة فقط','Confirmer · simulation'):t('التالي','Continuer')}${icon('arrow')}</button></div></div></form>`;}
function editor() {return `${header(true)}<main id="main" class="wrap editor-wrap">${editorBody()}</main>${footer()}`;}
function buyer() {return `${header(true)}<main id="main" class="wrap buyer"><div class="workspace-welcome"><div><span class="eyebrow">${t('مساحة المشتري','ESPACE ACHETEUR')}</span><h1>${t('طلباتك، خطوة بخطوة','Vos demandes, étape par étape')}</h1><p>${t('تابع الردود واتخذ قرارك على العرض الحالي فقط.','Suivez les réponses et décidez uniquement sur l’offre actuelle.')}</p></div><a href="${href('home')}" class="btn primary">${t('تصفح المنتجات','Parcourir les produits')}</a></div><nav class="local-tabs"><a class="active" href="${href('buyer')}">${t('طلبات الأسعار','Demandes de devis')} <span>2</span></a><a href="${href('messages')}">${t('المحادثات','Conversations')}</a><button class="plain" data-demo>${t('طلبات التوريد','Approvisionnement')}</button></nav><section class="buyer-request panel"><img src="assets/ceramics.svg" width="180" height="135" alt="${esc(p.name)}"><div><span class="status published">${t('وصل عرض سعر','Offre reçue')}</span><h2>${p.name}</h2><p>${t('96 قطعة · دار التوريد · مرجع تجريبي RFQ-001','96 pièces · Dar Appro · Référence fictive RFQ-001')}</p><p class="quiet">${t('لم تقبل هذا العرض بعد. راجع الشروط وسجل العروض.','Cette offre n’est pas acceptée. Vérifiez les conditions et l’historique.')}</p></div><a class="btn primary" href="${href('messages')}">${t('مراجعة العرض والمحادثة','Voir l’offre et la conversation')}</a></section><section class="panel state-note"><h2>${t('حالات الاتفاق تبقى واضحة','Des états sans ambiguïté')}</h2><p>${t('بانتظار المورد ← وصل العرض ← قرار قيد الاستكمال ← اتفاق مثبت. العرض السابق لا يقبل مجدداً، والاتفاق المثبت يحتفظ ببياناته.','En attente → Offre reçue → Finalisation en cours → Accord figé. Une offre antérieure ne peut pas être acceptée à nouveau ; l’accord conserve ses données.')}</p></section></main>${footer()}`;}
function messages() {return `${header(true)}<main id="main" class="wrap messages"><div class="section-head"><h1>${t('العرض والمحادثة','Offre et conversation')}</h1><a class="text-link" href="${href('buyer')}">${t('كل الطلبات','Toutes les demandes')}</a></div><div class="conversation-layout"><section class="conversation panel"><div class="conversation-head"><span class="store-avatar">د</span><div><strong>${t('دار التوريد','Dar Appro')}</strong><p>${t('طلب 96 قطعة · RFQ-001 تجريبي','96 pièces · RFQ-001 fictif')}</p></div><span class="status published">${t('مفتوحة','Ouverte')}</span></div><div class="message-list" id="message-list"><p class="message-date">${t('محادثة توضيحية — ليست مراسلة حقيقية','Conversation fictive — aucun message réel')}</p><div class="bubble mine">${t('أرغب في عرض لـ96 قطعة. هل يمكن توضيح السعر والشروط؟','Je souhaite un devis pour 96 pièces. Pouvez-vous préciser le prix et les conditions ?')}<small>10:20</small></div><div class="bubble theirs">${t('أرفقت العرض الحالي للمراجعة. يُرجى تأكيد المواصفات قبل اتخاذ القرار.','Voici l’offre actuelle à examiner. Merci de confirmer les spécifications avant votre décision.')}<small>10:24</small></div></div><form class="message-composer" id="message-form"><label class="sr-only" for="message">${t('رسالتك','Votre message')}</label><input id="message" required placeholder="${t('اكتب رسالة توضيحية…','Écrivez un message de démonstration…')}"><button class="btn primary">${t('معاينة الإرسال','Simuler l’envoi')}</button></form></section><aside class="offer-summary panel"><span class="eyebrow">${t('العرض الحالي · عينة','OFFRE ACTUELLE · EXEMPLE')}</span><h2>${p.name}</h2><strong class="offer-price">${money(39)} <small>/ ${p.unit}</small></strong><dl class="specs"><div><dt>${t('الكمية','Quantité')}</dt><dd>96 ${p.unit}</dd></div><div><dt>${t('الإجمالي','Total')}</dt><dd>${money(3744)}</dd></div><div><dt>${t('المهلة المقترحة','Délai proposé')}</dt><dd>${t('7 أيام','7 jours')}</dd></div><div><dt>${t('الشروط','Conditions')}</dt><dd>${t('شروط توضيحية يحددها المورد؛ لا دفع هنا','Conditions fictives à définir ; aucun paiement ici')}</dd></div></dl><button class="btn primary" data-agreement>${t('مراجعة قبل القبول','Vérifier avant d’accepter')}</button><button class="text-link" data-demo>${t('سجل العروض السابقة','Historique des offres')}</button><p class="quiet">${t('لا تُحفظ قرارات في هذا النموذج. يبقى منطق B كما هو.','Aucune décision n’est enregistrée. La logique B reste inchangée.')}</p></aside></div></main>${footer()}`;}
function comparePage() {return `${header()}<main id="main" class="wrap comparison"><div class="section-head"><div><span class="eyebrow">${t('بيانات متجاورة، قرار أوضح','CÔTE À CÔTE, PLUS CLAIR')}</span><h1>${t('قارن شروط الجملة','Comparez les conditions de gros')}</h1></div><a href="${href('home')}" class="text-link">${t('متابعة التصفح','Continuer à explorer')}</a></div><p class="quiet">${t('عينة للعرض فقط. اختلاف الوحدة أوالعملة يمنع مقارنة السعر وحده.','Exemple visuel. Des unités ou devises différentes interdisent une comparaison du prix seul.')}</p><div class="comparison-scroll" tabindex="0" role="region" aria-label="${t('جدول المقارنة، قابل للتمرير','Tableau comparatif défilant')}"><table><caption>${t('عينتان اصطناعيتان من المنتجات','Deux produits fictifs')}</caption><thead><tr><th>${t('المعلومة','Critère')}</th>${[p,products[3]].map(q=>`<th><img src="assets/${q.img}.svg" width="180" height="135" alt=""><strong>${q.name}</strong></th>`).join('')}</tr></thead><tbody>${[[t('سعر الوحدة','Prix unitaire'),money(42),money(75)],[t('وحدة البيع','Unité'),p.unit,products[3].unit],['MOQ',48,20],[t('المدينة','Ville'),p.city,products[3].city],[t('التقييمات','Avis'),t('لا توجد في العينة','Aucun dans cet exemple'),t('لا توجد في العينة','Aucun dans cet exemple')]].map(row=>`<tr>${row.map((v,i)=>i?`<td>${v}</td>`:`<th scope="row">${v}</th>`).join('')}</tr>`).join('')}</tbody></table></div></main>${footer()}`;}
function footer() {return `<footer class="footer wrap">${brand}<p>${t('سوق جملة مغربي. التصميم للمراجعة فقط.','Un marché de gros marocain. Prototype pour revue uniquement.')}</p><span>${t('لا بيع أو دفع أو شحن في هذا النموذج','Aucune vente, aucun paiement ni transport dans ce prototype')}</span></footer><div id="compare-tray" class="compare-tray" hidden></div>`;}
document.getElementById('app').innerHTML = ({home,product,store,supplier,editor,buyer,messages,compare:comparePage}[page])();
document.getElementById('main').setAttribute('tabindex','-1');
const toast = message => {const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500);};
const dialog = document.getElementById('dialog');
dialog.addEventListener('keydown', event => {
  if (event.key !== 'Tab') return;
  const nodes = [...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select,textarea,a[href]')].filter(el => el.getClientRects().length);
  const first = nodes[0], last = nodes.at(-1);
  if (!first) return;
  if (event.shiftKey && (document.activeElement === first || !dialog.contains(document.activeElement))) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && (document.activeElement === last || !dialog.contains(document.activeElement))) { event.preventDefault(); first.focus(); }
});
const demoNotice = () => toast(t('نموذج للمراجعة فقط؛ لم يُحفظ أو يُرسل شيء.','Prototype uniquement ; rien n’a été enregistré ni envoyé.'));
function modal(title, content) {document.getElementById('dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-close aria-label="${t('إغلاق','Fermer')}">${icon('close')}</button></div>${content}`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();}
function rfqForm() {modal(t('طلب عرض سعر','Demander un devis'),`<p class="quiet">${t('حساب مشتري توضيحي · لا اتصال بالخادم','Compte acheteur fictif · aucune connexion au serveur')}</p><div class="rfq-product"><img src="assets/ceramics.svg" width="90" height="68" alt=""><strong>${p.name}<small>${t('أقل طلب 48 قطعة · MAD','Minimum 48 pièces · MAD')}</small></strong></div><form id="rfq-form" class="fields">${field('quantity',t('الكمية المطلوبة','Quantité demandée'),'48','number','min="48" required')}${field('phone',t('هاتف تجريبي','Téléphone fictif'),'+212600000000','tel','required')}${field('city',t('المدينة','Ville'),t('الرباط','Rabat'))}<label class="field">${t('المواصفات والملاحظات · اختياري','Spécifications et remarques · facultatif')}<textarea rows="3" name="notes"></textarea></label><button class="btn primary">${t('معاينة الطلب فقط','Prévisualiser seulement')}</button></form>`);}
const selected = new Set();
function updateTray() {const el=document.getElementById('compare-tray');if(!el)return;el.hidden=!selected.size;el.innerHTML=`<span>${icon('compare')}${selected.size} / 4 ${t('للمقارنة','à comparer')}</span><a class="btn primary" href="${href('compare')}">${t('فتح عينة المقارنة','Voir l’exemple comparatif')}</a><button class="icon-button" data-clear aria-label="${t('مسح المقارنة','Effacer la comparaison')}">${icon('close')}</button>`;document.querySelectorAll('[data-compare]').forEach(b=>b.setAttribute('aria-pressed',String(selected.has(b.dataset.compare))));}
let query='', category=null, city='';
function renderProducts() {let list=products.filter(q=>(!query||`${q.name} ${q.category} ${q.city}`.toLowerCase().includes(query.toLowerCase()))&&(!category||q.category===category)&&(!city||q.city===city));if(document.getElementById('sort')?.value==='asc')list.sort((a,b)=>a.price-b.price);const grid=document.getElementById('product-grid');if(grid)grid.innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h2>${t('لم نجد نتيجة في العينة','Aucun résultat dans cet exemple')}</h2><button class="btn outline" data-reset>${t('مسح البحث','Effacer la recherche')}</button></div>`;const status=document.getElementById('search-status');if(status){status.hidden=false;status.textContent=t(`${list.length} نتائج في البيانات التوضيحية`,`${list.length} résultat(s) dans les données fictives`);}updateTray();}
document.addEventListener('click', e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.hasAttribute('data-rfq'))modal(t('أرسل طلبك من حساب المشتري','Envoyez depuis votre compte acheteur'),`<p>${t('يمكنك التصفح دون حساب. إرسال الطلب ومتابعة عرض المورد يحتاجان تسجيل الدخول، مع العودة إلى هذا المنتج.','La consultation est libre. L’envoi et le suivi nécessitent une connexion, puis le retour à ce produit.')}</p><button class="btn primary" data-preview-buyer>${t('استعراض النموذج كمشترٍ تجريبي','Explorer le formulaire avec un acheteur fictif')}</button><p class="quiet">${t('لا ينشئ النموذج حساباً ولا يرسل طلباً.','Ce prototype ne crée aucun compte et n’envoie aucune demande.')}</p>`);
 if(b.hasAttribute('data-preview-buyer'))rfqForm();
 if(b.hasAttribute('data-close'))dialog.close();
 if(b.hasAttribute('data-demo')||b.hasAttribute('data-save')||b.hasAttribute('data-ai'))demoNotice();
 if(b.hasAttribute('data-image'))modal(t('البحث بالصورة','Recherche par image'),`<p>${t('في التنفيذ تبقى سياسة C1: تصفح صور الكتالوج عام، والرفع والبحث بالصورة يتبعان صلاحيات الحساب. لا نفترض رفعاً مجهولاً.','À l’implémentation, conserver C1 : consultation publique, import et recherche visuelle selon les droits du compte. Aucun import anonyme supposé.')}</p><button class="btn outline" data-close>${t('فهمت','Compris')}</button>`);
 if(b.hasAttribute('data-share'))modal(t('رابط قابل للمشاركة','Un lien à partager'),`<p>${t('الروابط المستقرة من C2 تبقى كما هي عند التنفيذ. هذا رابط المعاينة فقط.','Les liens stables de C2 sont conservés à l’implémentation. Ceci est uniquement le lien du prototype.')}</p><label class="field">${t('رابط المعاينة','Lien de prévisualisation')}<input value="${esc(location.href)}" readonly dir="ltr"></label><button class="btn primary" data-copy-preview>${icon('copy')}${t('نسخ رابط المعاينة','Copier le lien du prototype')}</button>`);
 if(b.hasAttribute('data-copy-preview'))navigator.clipboard?.writeText(location.href).then(()=>toast(t('تم نسخ رابط المعاينة.','Lien du prototype copié.'))).catch(()=>toast(t('حدد الرابط وانسخه يدوياً.','Sélectionnez le lien et copiez-le.')));
 if(b.hasAttribute('data-compare')){selected.has(b.dataset.compare)?selected.delete(b.dataset.compare):selected.size<4&&selected.add(b.dataset.compare);updateTray();}
 if(b.hasAttribute('data-clear')){selected.clear();updateTray();}
 if(b.hasAttribute('data-category')){const i=Number(b.dataset.category);category=i===3?null:[products[0].category,products[1].category,products[2].category][i];document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));renderProducts();document.getElementById('catalog')?.scrollIntoView({behavior:'smooth'});}
 if(b.hasAttribute('data-reset')){query='';category=null;city='';document.querySelectorAll('[data-search] input[name=q]').forEach(x=>x.value='');renderProducts();}
 if(b.hasAttribute('data-filters'))modal(t('تصفية المنتجات','Filtrer les produits'),`<form id="filter-form" class="fields"><label class="field">${t('المدينة','Ville')}<select name="city"><option value="">${t('كل المدن','Toutes les villes')}</option>${products.map(q=>`<option>${q.city}</option>`).join('')}</select></label><button class="btn primary">${t('تطبيق على العينة','Appliquer à l’exemple')}</button></form>`);
 if(b.hasAttribute('data-thumb')){document.getElementById('main-product-image').src=`assets/${b.dataset.thumb}.svg`;document.querySelectorAll('[data-thumb]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});}
 if(b.hasAttribute('data-prev')){captureEditor();step--;renderEditor();}
 if(b.hasAttribute('data-verification'))modal(t('توثيق اختياري، دون وعود','Vérification facultative, sans promesses'),`<p>${t('اقتراح عرض لحالات unverified / pending / verified / rejected الموجودة فعلاً. لا شارة تجريبية ولا وعد بضمان الجودة أوالدفع. لا نبدأ نظام توثيق جديداً في D0.','Présentation proposée des états existants : unverified / pending / verified / rejected. Aucun badge fictif ni garantie de qualité ou de paiement. Aucun nouveau système en D0.')}</p><button class="btn outline" data-close>${t('إغلاق','Fermer')}</button>`);
 if(b.hasAttribute('data-agreement'))modal(t('مراجعة العرض الحالي','Vérifier l’offre actuelle'),`<p>${t('96 قطعة × 39 MAD = 3744 MAD. مهلة 7 أيام وشروط المورد كما تظهر في العرض.','96 pièces × 39 MAD = 3744 MAD. Délai de 7 jours et conditions du fournisseur indiquées dans l’offre.')}</p><p>${t('في التنفيذ: عرض رقم العرض، النسخة المثبتة للمنتج، حالة الاستكمال، ومنع قبول العرض السابق. لا قرار حقيقياً هنا.','À l’implémentation : référence, produit figé, état de finalisation, et rejet des offres antérieures. Aucune décision réelle ici.')}</p><button class="btn outline" data-close>${t('العودة للمراجعة','Revenir à la revue')}</button>`);
});
function captureEditor(){const form=document.getElementById('editor-form');if(!form)return;for(const [key,value] of new FormData(form).entries())if(key in editorData)editorData[key]=value;for(const key of ['rights','approved'])if(form.elements[key])editorData[key]=form.elements[key].checked;}
function renderEditor(){document.getElementById('main').innerHTML=editorBody();document.getElementById('step-heading').focus();}
document.addEventListener('change',e=>{if(e.target.id==='sort')renderProducts();if(e.target.name==='approved'){captureEditor();document.getElementById('editor-next').disabled=!editorData.approved||!editorData.rights||editorData.availability==='unknown';}});
document.addEventListener('input',e=>{if(e.target.id==='quantity'){const n=Number(e.target.value),price=n>=240?36:n>=96?39:42;document.getElementById('estimate').innerHTML=n<48?t('الكمية أقل من الحد الأدنى.','Quantité inférieure au minimum.'):`${t('تقدير أولي','Estimation indicative')} <strong>${money(n*price)}</strong> · ${t('ليس اتفاقاً تجارياً','ne vaut pas accord')}`;}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;
 if(f.matches('[data-search]')){query=String(new FormData(f).get('q')||'').trim();if(!document.getElementById('product-grid')){toast(t('هذا البحث تمثيلي؛ افتح السوق لاستعراض الفلترة.','Recherche de démonstration ; ouvrez le marché pour filtrer.'));return;}renderProducts();document.getElementById('catalog')?.scrollIntoView({behavior:'smooth'});}
 if(f.id==='filter-form'){city=String(new FormData(f).get('city')||'');dialog.close();renderProducts();}
 if(f.id==='editor-form'){captureEditor();if(step<3){step++;renderEditor();}else demoNotice();}
 if(f.id==='rfq-form'){const n=new FormData(f).get('quantity');modal(t('مراجعة الطلب · لا إرسال','Vérifier la demande · aucun envoi'),`<p>${esc(p.name)} · ${esc(n)} ${p.unit}</p><p>${t('هذه نهاية التفاعل التوضيحي. لم ينشأ طلب RFQ أوحساب أواتفاق.','Fin du parcours de démonstration. Aucune demande, aucun compte et aucun accord créés.')}</p><button class="btn primary" data-close>${t('إغلاق المعاينة','Fermer l’aperçu')}</button>`);}
 if(f.id==='message-form'){const input=f.elements.message;const text=input.value.trim();if(text){const el=document.createElement('div');el.className='bubble mine';el.textContent=text;document.getElementById('message-list').append(el);input.value='';toast(t('رسالة محلية في النموذج فقط.','Message local au prototype uniquement.'));}}
});
